test "secp256k1_recover arena wrapper exposes 64-byte success-shaped result" {
    var buf: [128]u8 align(8) = undefined;
    var arena = Arena.fromStaticBuffer(&buf);
    const hash = [_]u8{0x11} ** secp256k1_hash_len;
    const signature = [_]u8{0x22} ** secp256k1_signature_len;

    const pubkey = sol_secp256k1_recover_alloc(&arena, &hash, 1, &signature);
    try std.testing.expectEqual(@as(usize, secp256k1_pubkey_len), pubkey.len);
    try std.testing.expectEqual(@as(usize, secp256k1_pubkey_len), arena.offset);
}

test "secp256k1_recover arena wrapper maps invalid recovery id to zero-length bytes" {
    var buf: [128]u8 align(8) = undefined;
    var arena = Arena.fromStaticBuffer(&buf);
    const hash = [_]u8{0x11} ** secp256k1_hash_len;
    const signature = [_]u8{0x22} ** secp256k1_signature_len;

    const too_large = sol_secp256k1_recover_alloc(&arena, &hash, 4, &signature);
    try std.testing.expectEqual(@as(usize, 0), too_large.len);
    try std.testing.expectEqual(@as(usize, 0), arena.offset);

    const negative = sol_secp256k1_recover_alloc(&arena, &hash, -1, &signature);
    try std.testing.expectEqual(@as(usize, 0), negative.len);
    try std.testing.expectEqual(@as(usize, 0), arena.offset);
}

test "secp256k1_recover arena wrapper maps invalid input lengths to zero-length bytes" {
    var buf: [128]u8 align(8) = undefined;
    var arena = Arena.fromStaticBuffer(&buf);
    const hash_short = [_]u8{0x11} ** 31;
    const hash = [_]u8{0x11} ** secp256k1_hash_len;
    const signature_short = [_]u8{0x22} ** 63;

    try std.testing.expectEqual(@as(usize, 0), sol_secp256k1_recover_alloc(&arena, &hash_short, 1, &signature_short).len);
    try std.testing.expectEqual(@as(usize, 0), sol_secp256k1_recover_alloc(&arena, &hash, 1, &signature_short).len);
    try std.testing.expectEqual(@as(usize, 0), arena.offset);
}

test "secp256k1_recover_into_account_data rejects recovery id out of range" {
    var account_data: [secp256k1_pubkey_len]u8 = undefined;
    const hash = [_]u8{0x11} ** secp256k1_hash_len;
    const signature = [_]u8{0x22} ** secp256k1_signature_len;

    try std.testing.expect(sol_secp256k1_recover_into_account_data(&account_data, &hash, 4, &signature) != 0);
    try std.testing.expect(sol_secp256k1_recover_into_account_data(&account_data, &hash, -1, &signature) != 0);
}

test "secp256k1_recover_into_account_data rejects short account data" {
    var account_data: [secp256k1_pubkey_len - 1]u8 = undefined;
    const hash = [_]u8{0x11} ** secp256k1_hash_len;
    const signature = [_]u8{0x22} ** secp256k1_signature_len;

    try std.testing.expect(sol_secp256k1_recover_into_account_data(&account_data, &hash, 1, &signature) != 0);
}

test "secp256k1_recover_into_account_data hosted stub fills account data" {
    var account_data = [_]u8{0xaa} ** (secp256k1_pubkey_len + 4);
    const hash = [_]u8{0x11} ** secp256k1_hash_len;
    const signature = [_]u8{0x22} ** secp256k1_signature_len;

    const rc = sol_secp256k1_recover_into_account_data(&account_data, &hash, 2, &signature);
    try std.testing.expectEqual(@as(i64, 0), rc);
    try std.testing.expectEqual(@as(u8, 2), account_data[0]);
    try std.testing.expectEqual(@as(u8, 0), account_data[1]);
    try std.testing.expectEqual(@as(u8, 0), account_data[secp256k1_pubkey_len - 1]);
    try std.testing.expectEqual(@as(u8, 0xaa), account_data[secp256k1_pubkey_len]);
}

//! Solana cross-program invocation and return-data runtime bindings.
//!
//! RESPONSIBILITIES:
//! - Define the C ABI structs consumed by Solana CPI and PDA syscalls.
//! - Centralize MurmurHash3-32 dispatch addresses for CPI-related syscalls.
//! - Provide deterministic hosted fallbacks for PDA and return-data tests.

const std = @import("std");
const builtin = @import("builtin");
const Arena = @import("arena.zig").Arena;
const account = @import("account.zig");
const syscalls = @import("syscalls.zig");

/// 32-byte Solana public key.
pub const Pubkey = syscalls.Pubkey;

/// Maximum Solana PDA seed length in bytes.
pub const max_seed_len: usize = 32;
/// Maximum number of seeds accepted by Solana PDA helpers.
pub const max_seeds: usize = 16;
/// Domain separator appended by Solana PDA derivation.
pub const pda_marker = "ProgramDerivedAddress";

/// C ABI account metadata for a CPI instruction.
pub const SolAccountMeta = extern struct {
    pubkey: *const Pubkey,
    is_writable: u8,
    is_signer: u8,
};

/// C ABI instruction descriptor consumed by `sol_invoke_signed_c`.
pub const SolInstruction = extern struct {
    program_id: *const Pubkey,
    accounts: [*]const SolAccountMeta,
    account_len: u64,
    data: [*]const u8,
    data_len: u64,

    /// Builds a C instruction descriptor from Zig slices.
    pub fn fromSlices(program_id: *const Pubkey, accounts: []const SolAccountMeta, data: []const u8) SolInstruction {
        return .{
            .program_id = program_id,
            .accounts = accounts.ptr,
            .account_len = accounts.len,
            .data = data.ptr,
            .data_len = data.len,
        };
    }
};

/// C ABI account-info descriptor passed to CPI.
pub const SolAccountInfo = extern struct {
    key: *const Pubkey,
    lamports: *align(1) u64,
    data_len: u64,
    data: [*]u8,
    owner: *const Pubkey,
    rent_epoch: u64,
    is_signer: u8,
    is_writable: u8,
    executable: u8,
};

/// C ABI one-seed byte slice.
pub const SolSignerSeed = extern struct {
    addr: [*]const u8,
    len: u64,

    /// Builds one C seed descriptor from a Zig byte slice.
    pub fn fromSlice(seed: []const u8) SolSignerSeed {
        return .{ .addr = seed.ptr, .len = seed.len };
    }
};

/// High-level signer seed collection used by hosted helpers and tests.
pub const SolSignerSeeds = struct {
    seeds: []const SolSignerSeed,

    /// Exposes the collection as the C ABI descriptor.
    pub fn toC(self: SolSignerSeeds) SolSignerSeedsC {
        return .{ .addr = self.seeds.ptr, .len = self.seeds.len };
    }
};

/// C ABI signer-seed collection consumed by `sol_invoke_signed_c`.
pub const SolSignerSeedsC = extern struct {
    addr: [*]const SolSignerSeed,
    len: u64,
};

/// MurmurHash3-32 dispatch address for `sol_invoke_signed_c`.
pub const sol_invoke_signed_c_address: usize = 0xa22b9c85;
/// MurmurHash3-32 dispatch address for `sol_create_program_address`.
pub const sol_create_program_address_address: usize = 0x9377323c;
/// MurmurHash3-32 dispatch address for `sol_try_find_program_address`.
pub const sol_try_find_program_address_address: usize = 0x48504a38;
/// MurmurHash3-32 dispatch address for `sol_set_return_data`.
pub const sol_set_return_data_address: usize = 0xa226d3eb;
/// MurmurHash3-32 dispatch address for `sol_get_return_data`.
pub const sol_get_return_data_address: usize = 0x5d2245e4;

const success: u64 = 0;
const invalid_seeds: u64 = 1;
const return_data_capacity: usize = 1024;
const is_bpf = builtin.target.cpu.arch == .bpfel or builtin.target.cpu.arch == .bpfeb;

const SolInvokeSignedCFn = *align(1) const fn (*const SolInstruction, [*]const SolAccountInfo, u64, [*]const SolSignerSeedsC, u64) u64;
const SolCreateProgramAddressFn = *align(1) const fn ([*]const SolSignerSeed, u64, *const Pubkey, *Pubkey) u64;
const SolTryFindProgramAddressFn = *align(1) const fn ([*]const SolSignerSeed, u64, *const Pubkey, *Pubkey, *u8) u64;
const SolSetReturnDataFn = *align(1) const fn ([*]const u8, u64) void;
const SolGetReturnDataFn = *align(1) const fn ([*]u8, u64, *Pubkey) u64;

var hosted_return_program_id: Pubkey = [_]u8{0} ** 32;
var hosted_return_data: [return_data_capacity]u8 = undefined;
var hosted_return_data_len: usize = 0;
var bpf_return_program_id: Pubkey = undefined;
var bpf_return_data: [return_data_capacity]u8 = undefined;

/// Converts a parsed account view into a CPI account-info descriptor.
pub fn accountInfoFromView(view: account.AccountView) SolAccountInfo {
    return .{
        .key = view.key,
        .lamports = view.lamports,
        .data_len = view.data.len,
        .data = view.data.ptr,
        .owner = view.owner,
        .rent_epoch = view.rentEpochValue(),
        .is_signer = @intFromBool(view.is_signer),
        .is_writable = @intFromBool(view.is_writable),
        .executable = @intFromBool(view.executable),
    };
}

/// Invokes another Solana program with optional signer seeds.
pub inline fn sol_invoke_signed_c(instruction: *const SolInstruction, account_infos: []const SolAccountInfo, signer_seeds: []const SolSignerSeedsC) u64 {
    if (comptime is_bpf) {
        const syscall: SolInvokeSignedCFn = @ptrFromInt(sol_invoke_signed_c_address);
        if (signer_seeds.len == 0) {
            var empty_seed_bytes = [_]u8{0};
            var empty_seed = [_]SolSignerSeed{.{ .addr = empty_seed_bytes[0..].ptr, .len = 0 }};
            var empty_seed_groups = [_]SolSignerSeedsC{.{ .addr = empty_seed[0..].ptr, .len = 0 }};
            return syscall(instruction, account_infos.ptr, account_infos.len, empty_seed_groups[0..].ptr, 0);
        }
        return syscall(instruction, account_infos.ptr, account_infos.len, signer_seeds.ptr, signer_seeds.len);
    } else {
        return success;
    }
}

/// Invokes another Solana program without PDA signer seeds.
pub inline fn invoke(instruction: *const SolInstruction, account_infos: []const SolAccountInfo) u64 {
    const empty: []const SolSignerSeedsC = &.{};
    return sol_invoke_signed_c(instruction, account_infos, empty);
}

/// Invokes the system program to transfer one lamport from account 0 to account 1.
pub inline fn zxcaml_system_transfer_one_lamport(arena: *Arena, input: [*]const u8) u64 {
    _ = arena;
    const input_mut: [*]u8 = @constCast(input);
    var cursor: usize = 0;
    _ = readU64Raw(input_mut, &cursor);

    var infos: [3]SolAccountInfo = undefined;
    parseAccountInfoUnchecked(input_mut, &cursor, &infos[0]);
    parseAccountInfoUnchecked(input_mut, &cursor, &infos[1]);
    parseAccountInfoUnchecked(input_mut, &cursor, &infos[2]);

    var program_id = infos[2].key.*;
    var metas: [2]SolAccountMeta = undefined;
    metas[0] = .{ .pubkey = infos[0].key, .is_writable = 1, .is_signer = 1 };
    metas[1] = .{ .pubkey = infos[1].key, .is_writable = 1, .is_signer = 0 };

    var data: [12]u8 = undefined;
    data[0] = 2;
    data[1] = 0;
    data[2] = 0;
    data[3] = 0;
    data[4] = 1;
    data[5] = 0;
    data[6] = 0;
    data[7] = 0;
    data[8] = 0;
    data[9] = 0;
    data[10] = 0;
    data[11] = 0;

    const instruction: SolInstruction = .{
        .program_id = &program_id,
        .accounts = metas[0..].ptr,
        .account_len = 2,
        .data = data[0..].ptr,
        .data_len = data.len,
    };

    var seed: [6]u8 = undefined;
    seed[0] = 'z';
    seed[1] = 'x';
    seed[2] = 'c';
    seed[3] = 'a';
    seed[4] = 'm';
    seed[5] = 'l';
    var c_seeds = [_]SolSignerSeed{.{ .addr = seed[0..].ptr, .len = seed.len }};
    var seed_groups = [_]SolSignerSeedsC{.{ .addr = c_seeds[0..].ptr, .len = c_seeds.len }};
    return sol_invoke_signed_c(&instruction, infos[0..], seed_groups[0..]);
}

/// Invokes the system program transfer using already parsed account views.
pub inline fn zxcaml_system_transfer_one_lamport_from_views(arena: *Arena, views: []account.AccountView) u64 {
    if (views.len < 3) return 1;

    var program_id = views[2].key.*;
    var metas: [2]SolAccountMeta = undefined;
    metas[0] = .{
        .pubkey = views[0].key,
        .is_writable = 1,
        .is_signer = 1,
    };
    metas[1] = .{
        .pubkey = views[1].key,
        .is_writable = 1,
        .is_signer = 0,
    };

    var data: [12]u8 = undefined;
    data[0] = 2;
    data[1] = 0;
    data[2] = 0;
    data[3] = 0;
    data[4] = 1;
    data[5] = 0;
    data[6] = 0;
    data[7] = 0;
    data[8] = 0;
    data[9] = 0;
    data[10] = 0;
    data[11] = 0;
    const instruction: SolInstruction = .{
        .program_id = &program_id,
        .accounts = metas[0..].ptr,
        .account_len = metas.len,
        .data = data[0..].ptr,
        .data_len = data.len,
    };

    var infos: []SolAccountInfo = undefined;
    arena.allocIntoOrTrap(SolAccountInfo, views.len, &infos);
    for (views, 0..) |view, index| {
        infos[index] = .{
            .key = view.key,
            .lamports = view.lamports,
            .data_len = view.data.len,
            .data = view.data.ptr,
            .owner = view.owner,
            .rent_epoch = view.rentEpochValue(),
            .is_signer = @intFromBool(view.is_signer),
            .is_writable = @intFromBool(view.is_writable),
            .executable = @intFromBool(view.executable),
        };
    }

    var seed: [6]u8 = undefined;
    seed[0] = 'z';
    seed[1] = 'x';
    seed[2] = 'c';
    seed[3] = 'a';
    seed[4] = 'm';
    seed[5] = 'l';
    var c_seeds = [_]SolSignerSeed{.{ .addr = seed[0..].ptr, .len = seed.len }};
    var seed_groups = [_]SolSignerSeedsC{.{ .addr = c_seeds[0..].ptr, .len = c_seeds.len }};
    return sol_invoke_signed_c(&instruction, infos, seed_groups[0..]);
}

fn writeSystemTransferData(out: []u8, amount: u64) void {
    out[0] = 2;
    out[1] = 0;
    out[2] = 0;
    out[3] = 0;
    out[4] = @intCast(amount & 0xff);
    out[5] = @intCast((amount >> 8) & 0xff);
    out[6] = @intCast((amount >> 16) & 0xff);
    out[7] = @intCast((amount >> 24) & 0xff);
    out[8] = @intCast((amount >> 32) & 0xff);
    out[9] = @intCast((amount >> 40) & 0xff);
    out[10] = @intCast((amount >> 48) & 0xff);
    out[11] = @intCast((amount >> 56) & 0xff);
}

fn pubkeyEq(lhs: *const Pubkey, rhs: *const Pubkey) bool {
    return std.mem.eql(u8, lhs[0..], rhs[0..]);
}

inline fn readU64Raw(input: [*]const u8, cursor: *usize) u64 {
    const start = cursor.*;
    cursor.* += 8;
    return @as(u64, input[start]) |
        (@as(u64, input[start + 1]) << 8) |
        (@as(u64, input[start + 2]) << 16) |
        (@as(u64, input[start + 3]) << 24) |
        (@as(u64, input[start + 4]) << 32) |
        (@as(u64, input[start + 5]) << 40) |
        (@as(u64, input[start + 6]) << 48) |
        (@as(u64, input[start + 7]) << 56);
}

inline fn parseAccountInfoUnchecked(input: [*]u8, cursor: *usize, out: *SolAccountInfo) void {
    _ = input[cursor.*];
    cursor.* += 1;
    const is_signer = input[cursor.*];
    cursor.* += 1;
    const is_writable = input[cursor.*];
    cursor.* += 1;
    const executable = input[cursor.*];
    cursor.* += 1;
    cursor.* += 4;
    const key: *const Pubkey = @ptrCast(input + cursor.*);
    cursor.* += 32;
    const owner: *const Pubkey = @ptrCast(input + cursor.*);
    cursor.* += 32;
    const lamports: *align(1) u64 = @ptrCast(input + cursor.*);
    cursor.* += @sizeOf(u64);
    const data_len = readU64Raw(input, cursor);
    const data = (input + cursor.*)[0..@intCast(data_len)];
    cursor.* += @intCast(data_len);
    cursor.* += 10 * 1024;
    cursor.* = std.mem.alignForward(usize, cursor.*, 8);
    const rent_epoch: *align(1) u64 = @ptrCast(input + cursor.*);
    cursor.* += @sizeOf(u64);

    out.* = .{
        .key = key,
        .lamports = lamports,
        .data_len = data.len,
        .data = data.ptr,
        .owner = owner,
        .rent_epoch = rent_epoch.*,
        .is_signer = is_signer,
        .is_writable = is_writable,
        .executable = executable,
    };
}

/// Derives a program address from seeds and a program id.
pub inline fn sol_create_program_address(seeds: []const SolSignerSeed, program_id: *const Pubkey, out: *Pubkey) u64 {
    if (comptime is_bpf) {
        const syscall: SolCreateProgramAddressFn = @ptrFromInt(sol_create_program_address_address);
        return syscall(seeds.ptr, seeds.len, program_id, out);
    }
    return createProgramAddressHosted(seeds, program_id, out);
}

/// Finds a valid program address and bump seed for a seed prefix.
pub inline fn sol_try_find_program_address(seeds: []const SolSignerSeed, program_id: *const Pubkey, out: *Pubkey, bump_seed: *u8) u64 {
    if (comptime is_bpf) {
        const syscall: SolTryFindProgramAddressFn = @ptrFromInt(sol_try_find_program_address_address);
        return syscall(seeds.ptr, seeds.len, program_id, out, bump_seed);
    }
    return tryFindProgramAddressHosted(seeds, program_id, out, bump_seed);
}

/// Stores return data for the current instruction.
pub inline fn sol_set_return_data(data: []const u8) void {
    if (comptime is_bpf) {
        const syscall: SolSetReturnDataFn = @ptrFromInt(sol_set_return_data_address);
        syscall(data.ptr, data.len);
    } else {
        hosted_return_data_len = @min(data.len, hosted_return_data.len);
        @memcpy(hosted_return_data[0..hosted_return_data_len], data[0..hosted_return_data_len]);
    }
}

/// Copies return data into `out` and writes the producing program id.
pub inline fn sol_get_return_data(out: []u8, program_id: *Pubkey) u64 {
    if (comptime is_bpf) {
        const syscall: SolGetReturnDataFn = @ptrFromInt(sol_get_return_data_address);
        return syscall(out.ptr, out.len, program_id);
    }
    const copy_len = @min(out.len, hosted_return_data_len);
    @memcpy(out[0..copy_len], hosted_return_data[0..copy_len]);
    program_id.* = hosted_return_program_id;
    return hosted_return_data_len;
}

/// Returns return data as an arena-owned byte slice for generated code.
pub inline fn sol_get_return_data_alloc(arena: *Arena) []const u8 {
    if (comptime is_bpf) {
        const total_len = sol_get_return_data(bpf_return_data[0..], &bpf_return_program_id);
        const copy_len: usize = @intCast(@min(total_len, @as(u64, bpf_return_data.len)));
        return bpf_return_data[0..copy_len];
    }
    var scratch: [return_data_capacity]u8 = undefined;
    var program_id: Pubkey = undefined;
    const total_len = sol_get_return_data(scratch[0..], &program_id);
    const copy_len = @min(total_len, scratch.len);
    const out = arena.alloc(u8, copy_len) catch unreachable;
    @memcpy(out, scratch[0..copy_len]);
    return out;
}

fn createProgramAddressHosted(seeds: []const SolSignerSeed, program_id: *const Pubkey, out: *Pubkey) u64 {
    if (!validateSeeds(seeds)) return invalid_seeds;

    var hasher = std.crypto.hash.sha2.Sha256.init(.{});
    for (seeds) |seed| {
        hasher.update(seed.addr[0..@intCast(seed.len)]);
    }
    hasher.update(program_id);
    hasher.update(pda_marker);
    hasher.final(out);

    return if (isOnCurve(out.*)) invalid_seeds else success;
}

fn tryFindProgramAddressHosted(seeds: []const SolSignerSeed, program_id: *const Pubkey, out: *Pubkey, bump_seed: *u8) u64 {
    if (seeds.len >= max_seeds or !validateSeeds(seeds)) return invalid_seeds;

    var bump: u16 = 255;
    while (true) : (bump -= 1) {
        const bump_byte: [1]u8 = .{@intCast(bump)};
        var all_seeds_buf: [max_seeds]SolSignerSeed = undefined;
        @memcpy(all_seeds_buf[0..seeds.len], seeds);
        all_seeds_buf[seeds.len] = SolSignerSeed.fromSlice(bump_byte[0..]);

        if (createProgramAddressHosted(all_seeds_buf[0 .. seeds.len + 1], program_id, out) == success) {
            bump_seed.* = @intCast(bump);
            return success;
        }
        if (bump == 0) break;
    }
    return invalid_seeds;
}

fn validateSeeds(seeds: []const SolSignerSeed) bool {
    if (seeds.len > max_seeds) return false;
    for (seeds) |seed| {
        if (seed.len > max_seed_len) return false;
    }
    return true;
}

fn isOnCurve(bytes: Pubkey) bool {
    _ = std.crypto.ecc.Edwards25519.fromBytes(bytes) catch return false;
    return true;
}

test "CPI syscall dispatch addresses match assigned MurmurHash3-32 values" {
    try std.testing.expectEqual(@as(usize, 0xa22b9c85), sol_invoke_signed_c_address);
    try std.testing.expectEqual(@as(usize, 0x9377323c), sol_create_program_address_address);
    try std.testing.expectEqual(@as(usize, 0x48504a38), sol_try_find_program_address_address);
    try std.testing.expectEqual(@as(usize, 0xa226d3eb), sol_set_return_data_address);
    try std.testing.expectEqual(@as(usize, 0x5d2245e4), sol_get_return_data_address);
}

test "CPI C ABI structs have stable field offsets" {
    try std.testing.expectEqual(@as(usize, 0), @offsetOf(SolAccountMeta, "pubkey"));
    try std.testing.expectEqual(@as(usize, 8), @offsetOf(SolAccountMeta, "is_writable"));
    try std.testing.expectEqual(@as(usize, 9), @offsetOf(SolAccountMeta, "is_signer"));
    try std.testing.expectEqual(@as(usize, 16), @sizeOf(SolAccountMeta));

    try std.testing.expectEqual(@as(usize, 0), @offsetOf(SolInstruction, "program_id"));
    try std.testing.expectEqual(@as(usize, 8), @offsetOf(SolInstruction, "accounts"));
    try std.testing.expectEqual(@as(usize, 16), @offsetOf(SolInstruction, "account_len"));
    try std.testing.expectEqual(@as(usize, 24), @offsetOf(SolInstruction, "data"));
    try std.testing.expectEqual(@as(usize, 32), @offsetOf(SolInstruction, "data_len"));
    try std.testing.expectEqual(@as(usize, 40), @sizeOf(SolInstruction));

    try std.testing.expectEqual(@as(usize, 16), @sizeOf(SolSignerSeed));
    try std.testing.expectEqual(@as(usize, 16), @sizeOf(SolSignerSeedsC));
}

test "hosted PDA derivation is deterministic and finds a bump" {
    var program_id: Pubkey = [_]u8{1} ** 32;
    const seed_bytes = "zxcaml";
    const seeds = [_]SolSignerSeed{SolSignerSeed.fromSlice(seed_bytes)};

    var bump: u8 = 0;
    var found: Pubkey = undefined;
    try std.testing.expectEqual(success, sol_try_find_program_address(seeds[0..], &program_id, &found, &bump));
    try std.testing.expect(bump <= 255);

    const bump_seed: [1]u8 = .{bump};
    const bumped_seeds = [_]SolSignerSeed{
        SolSignerSeed.fromSlice(seed_bytes),
        SolSignerSeed.fromSlice(bump_seed[0..]),
    };
    var first: Pubkey = undefined;
    var second: Pubkey = undefined;
    try std.testing.expectEqual(success, sol_create_program_address(bumped_seeds[0..], &program_id, &first));
    try std.testing.expectEqual(success, sol_create_program_address(bumped_seeds[0..], &program_id, &second));
    try std.testing.expectEqualSlices(u8, &first, &second);
    try std.testing.expectEqualSlices(u8, &found, &first);
}

test "hosted return data round-trips through set/get helpers" {
    sol_set_return_data("return payload");
    var out: [32]u8 = undefined;
    var program_id: Pubkey = undefined;

    const len = sol_get_return_data(out[0..], &program_id);
    try std.testing.expectEqual(@as(u64, "return payload".len), len);
    try std.testing.expectEqualSlices(u8, "return payload", out[0.."return payload".len]);

    var arena_buf: [64]u8 align(8) = undefined;
    var arena = Arena.fromStaticBuffer(&arena_buf);
    const allocated = sol_get_return_data_alloc(&arena);
    try std.testing.expectEqualSlices(u8, "return payload", allocated);
}

//! SPL Token runtime helpers for generated ZxCaml programs.
//!
//! RESPONSIBILITIES:
//! - Encode SPL Token Transfer instruction data without heap allocation.
//! - Parse canonical SPL Token account state into zero-copy pubkey views.
//! - Provide the canonical SPL Token program id and Transfer account metas.

const std = @import("std");
const Arena = @import("arena.zig").Arena;
const bs58 = @import("bs58.zig");
const cpi = @import("cpi.zig");

/// 32-byte Solana public key.
pub const Pubkey = cpi.Pubkey;

/// Length of a Solana public key in bytes.
pub const pubkey_len: usize = 32;
/// SPL Token Transfer instruction discriminator.
pub const transfer_discriminator: u8 = 3;
/// SPL Token Transfer instruction data length: one u8 discriminator plus u64 amount.
pub const transfer_instruction_data_len: usize = 9;
/// SPL Token InitializeAccount instruction discriminator.
pub const initialize_account_discriminator: u8 = 1;
/// SPL Token InitializeAccount instruction data length: one u8 discriminator.
pub const initialize_account_instruction_data_len: usize = 1;
/// SPL Token InitializeAccount account count: account, mint, owner, rent sysvar.
pub const initialize_account_account_count: usize = 4;
/// SPL Token Burn instruction discriminator.
pub const burn_discriminator: u8 = 8;
/// SPL Token Burn instruction data length: one u8 discriminator plus u64 amount.
pub const burn_instruction_data_len: usize = 9;
/// SPL Token Burn account count: account, mint, authority.
pub const burn_account_count: usize = 3;
/// SPL Token CloseAccount instruction discriminator.
pub const close_account_discriminator: u8 = 9;
/// SPL Token CloseAccount instruction data length: one u8 discriminator.
pub const close_account_instruction_data_len: usize = 1;
/// SPL Token CloseAccount account count: account, destination, authority.
pub const close_account_account_count: usize = 3;
/// SPL Token Revoke instruction discriminator.
pub const revoke_discriminator: u8 = 5;
/// SPL Token Revoke instruction data length: one u8 discriminator.
pub const revoke_instruction_data_len: usize = 1;
/// SPL Token Revoke account count: source, authority.
pub const revoke_account_count: usize = 2;
/// Canonical packed SPL Token account length.
pub const token_account_len: usize = 165;
const max_cpi_account_infos: usize = 4;
const pre_original_data_len_padding: usize = 4;
const max_permitted_data_increase: usize = 10 * 1024;
const account_alignment: usize = 8;

/// Canonical SPL Token program id as base58 for diagnostics and tests.
pub const program_id_base58 = "TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA";

/// Canonical SPL Token program id decoded at comptime from `TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA`.
pub const program_id: Pubkey = decodeProgramIdComptime();

/// Errors returned by SPL Token runtime helpers.
pub const Error = error{
    OutputTooShort,
    TruncatedInput,
    InvalidOptionTag,
};

/// Zero-copy view over the canonical SPL Token account state.
pub const TokenAccountView = struct {
    mint: *const Pubkey,
    owner: *const Pubkey,
    amount: u64,
    delegate: ?*const Pubkey,
    state: u8,
    is_native: ?u64,
    delegated_amount: u64,
    close_authority: ?*const Pubkey,
};

/// Writes the canonical SPL Token program id into a caller-owned stack or arena buffer.
pub inline fn writeProgramId(out: *Pubkey) void {
    out.* = program_id;
}

/// Writes an SPL Token program id from either raw bytes or the canonical base58 text.
pub fn writeProgramIdFromBytes(out: *Pubkey, bytes: []const u8) bool {
    if (bytes.len == pubkey_len) {
        @memcpy(out[0..], bytes[0..pubkey_len]);
        return true;
    }
    if (bytes.len == program_id_base58.len) {
        writeProgramId(out);
        return true;
    }
    return false;
}

fn decodeProgramIdComptime() Pubkey {
    @setEvalBranchQuota(20_000);
    var scratch: [128]u8 = undefined;
    var fixed = std.heap.FixedBufferAllocator.init(scratch[0..]);
    const decoded = bs58.decode(fixed.allocator(), program_id_base58) catch {
        @compileError("invalid SPL Token program id base58 literal");
    };
    if (decoded.len != pubkey_len) {
        @compileError("SPL Token program id must decode to 32 bytes");
    }
    var out: Pubkey = undefined;
    @memcpy(out[0..], decoded[0..pubkey_len]);
    return out;
}

/// Encodes SPL Token Transfer instruction data into a fixed-size array.
pub fn encodeTransfer(amount: u64) [transfer_instruction_data_len]u8 {
    var out: [transfer_instruction_data_len]u8 = undefined;
    _ = encodeTransferInto(out[0..], amount) catch unreachable;
    return out;
}

/// Encodes SPL Token Transfer instruction data into `out` and returns the written prefix.
pub fn encodeTransferInto(out: []u8, amount: u64) Error![]const u8 {
    if (out.len < transfer_instruction_data_len) return error.OutputTooShort;
    out[0] = transfer_discriminator;
    writeU64Le(out[1..transfer_instruction_data_len], amount);
    return out[0..transfer_instruction_data_len];
}

/// Encodes SPL Token InitializeAccount instruction data into a fixed-size array.
pub fn encodeInitializeAccount() [initialize_account_instruction_data_len]u8 {
    return .{initialize_account_discriminator};
}

/// Encodes SPL Token InitializeAccount instruction data into `out` and returns the written prefix.
pub fn encodeInitializeAccountInto(out: []u8) Error![]const u8 {
    if (out.len < initialize_account_instruction_data_len) return error.OutputTooShort;
    out[0] = initialize_account_discriminator;
    return out[0..initialize_account_instruction_data_len];
}

/// Builds account metas for Transfer: source writable, destination writable, authority signer.
pub fn transferAccountMetas(source: *const Pubkey, destination: *const Pubkey, authority: *const Pubkey) [3]cpi.SolAccountMeta {
    return .{
        .{ .pubkey = source, .is_writable = 1, .is_signer = 0 },
        .{ .pubkey = destination, .is_writable = 1, .is_signer = 0 },
        .{ .pubkey = authority, .is_writable = 0, .is_signer = 1 },
    };
}

/// Builds account metas for InitializeAccount: account writable, mint readonly, owner readonly, rent sysvar readonly.
pub fn initializeAccountMetas(account_pubkey: *const Pubkey, mint: *const Pubkey, owner: *const Pubkey, rent_sysvar: *const Pubkey) [initialize_account_account_count]cpi.SolAccountMeta {
    return .{
        .{ .pubkey = account_pubkey, .is_writable = 1, .is_signer = 0 },
        .{ .pubkey = mint, .is_writable = 0, .is_signer = 0 },
        .{ .pubkey = owner, .is_writable = 0, .is_signer = 0 },
        .{ .pubkey = rent_sysvar, .is_writable = 0, .is_signer = 0 },
    };
}

/// Builds an SPL Token InitializeAccount instruction using caller-owned meta/data buffers.
pub fn initializeAccountInstruction(
    account_pubkey: *const Pubkey,
    mint: *const Pubkey,
    owner: *const Pubkey,
    rent_sysvar: *const Pubkey,
    metas: *[initialize_account_account_count]cpi.SolAccountMeta,
    data: *[initialize_account_instruction_data_len]u8,
) cpi.SolInstruction {
    metas.* = initializeAccountMetas(account_pubkey, mint, owner, rent_sysvar);
    data.* = encodeInitializeAccount();
    return cpi.SolInstruction.fromSlices(&program_id, metas[0..], data[0..]);
}

/// Encodes SPL Token Burn instruction data into a fixed-size array.
pub fn encodeBurn(amount: u64) [burn_instruction_data_len]u8 {
    var out: [burn_instruction_data_len]u8 = undefined;
    _ = encodeBurnInto(out[0..], amount) catch unreachable;
    return out;
}

/// Encodes SPL Token Burn instruction data into `out` and returns the written prefix.
pub fn encodeBurnInto(out: []u8, amount: u64) Error![]const u8 {
    if (out.len < burn_instruction_data_len) return error.OutputTooShort;
    out[0] = burn_discriminator;
    writeU64Le(out[1..burn_instruction_data_len], amount);
    return out[0..burn_instruction_data_len];
}

/// Encodes SPL Token CloseAccount instruction data into a fixed-size array.
pub fn encodeCloseAccount() [close_account_instruction_data_len]u8 {
    return .{close_account_discriminator};
}

/// Encodes SPL Token CloseAccount instruction data into `out` and returns the written prefix.
pub fn encodeCloseAccountInto(out: []u8) Error![]const u8 {
    if (out.len < close_account_instruction_data_len) return error.OutputTooShort;
    out[0] = close_account_discriminator;
    return out[0..close_account_instruction_data_len];
}

/// Encodes SPL Token Revoke instruction data into a fixed-size array.
pub fn encodeRevoke() [revoke_instruction_data_len]u8 {
    return .{revoke_discriminator};
}

/// Encodes SPL Token Revoke instruction data into `out` and returns the written prefix.
pub fn encodeRevokeInto(out: []u8) Error![]const u8 {
    if (out.len < revoke_instruction_data_len) return error.OutputTooShort;
    out[0] = revoke_discriminator;
    return out[0..revoke_instruction_data_len];
}

/// Builds account metas for Burn: account writable, mint writable, authority signer.
pub fn burnAccountMetas(account_pubkey: *const Pubkey, mint: *const Pubkey, authority: *const Pubkey) [burn_account_count]cpi.SolAccountMeta {
    return .{
        .{ .pubkey = account_pubkey, .is_writable = 1, .is_signer = 0 },
        .{ .pubkey = mint, .is_writable = 1, .is_signer = 0 },
        .{ .pubkey = authority, .is_writable = 0, .is_signer = 1 },
    };
}

/// Builds an SPL Token Burn instruction using caller-owned meta/data buffers.
pub fn burnInstruction(
    account_pubkey: *const Pubkey,
    mint: *const Pubkey,
    authority: *const Pubkey,
    amount: u64,
    metas: *[burn_account_count]cpi.SolAccountMeta,
    data: *[burn_instruction_data_len]u8,
) cpi.SolInstruction {
    metas.* = burnAccountMetas(account_pubkey, mint, authority);
    data.* = encodeBurn(amount);
    return cpi.SolInstruction.fromSlices(&program_id, metas[0..], data[0..]);
}

/// Builds account metas for CloseAccount: account writable, destination writable, authority signer.
pub fn closeAccountAccountMetas(account_pubkey: *const Pubkey, destination: *const Pubkey, authority: *const Pubkey) [close_account_account_count]cpi.SolAccountMeta {
    return .{
        .{ .pubkey = account_pubkey, .is_writable = 1, .is_signer = 0 },
        .{ .pubkey = destination, .is_writable = 1, .is_signer = 0 },
        .{ .pubkey = authority, .is_writable = 0, .is_signer = 1 },
    };
}

/// Builds an SPL Token CloseAccount instruction using caller-owned meta/data buffers.
pub fn closeAccountInstruction(
    account_pubkey: *const Pubkey,
    destination: *const Pubkey,
    authority: *const Pubkey,
    metas: *[close_account_account_count]cpi.SolAccountMeta,
    data: *[close_account_instruction_data_len]u8,
) cpi.SolInstruction {
    metas.* = closeAccountAccountMetas(account_pubkey, destination, authority);
    data.* = encodeCloseAccount();
    return cpi.SolInstruction.fromSlices(&program_id, metas[0..], data[0..]);
}

/// Builds account metas for Revoke: source writable, authority signer.
pub fn revokeAccountMetas(source: *const Pubkey, authority: *const Pubkey) [revoke_account_count]cpi.SolAccountMeta {
    return .{
        .{ .pubkey = source, .is_writable = 1, .is_signer = 0 },
        .{ .pubkey = authority, .is_writable = 0, .is_signer = 1 },
