//! Solana BPF entrypoint shim for generated ZxCaml programs.
//!
//! RESPONSIBILITIES:
//! - Export the `entrypoint` symbol that Solana's loader discovers.
//! - Create the P1 32 KiB static-buffer arena for each invocation.
//! - Call the generated `omlz_user_entrypoint` function with arena threading.

const Arena = @import("runtime/arena.zig").Arena;
const AccountRuntime = @import("runtime/account.zig");
const syscalls = @import("runtime/syscalls.zig");
const program = @import("program.zig");

const arena_bytes = 32 * 1024;
const max_entrypoint_accounts = 64;

const loader_log_message linksection(".rodata") = "ZxCaml entrypoint".*;

/// Solana loader entrypoint; returns the user program's u64 status code.
export fn entrypoint(input: [*]u8) callconv(.c) u64 {
    // Minimal `return 0` programs can otherwise link to a section-only ELF that
    // `solana program deploy` rejects. A tiny log syscall keeps the dynamic
    // relocation/program-header shape expected by Solana's BPF loader.
    syscalls.sol_log_(loader_log_message[0..]);

    var bpf_arena_buffer: [arena_bytes]u8 align(8) = undefined;
    var arena = Arena.fromStaticBuffer(&bpf_arena_buffer);
    var account_storage: [max_entrypoint_accounts]AccountRuntime.AccountView = undefined;
    var accounts: []AccountRuntime.AccountView = undefined;
    AccountRuntime.parseAccountsFromPtrIntoStorage(input, account_storage[0..], &accounts) catch return 1;
    const instruction_data = AccountRuntime.parseInstructionDataFromPtr(input) catch return 1;
    const status = program.omlz_user_entrypoint(&arena, input, accounts, instruction_data);
    arena.reset();
    return status;
}

现在整个图景很清晰了。让我用代码来展示这个两层架构：

---

## 回答：两层都要写，分工不同

ZxCaml 的 Solana 支持是**双层架构**：

```
     你写的 OCaml (.ml)
        │
        │  external 声明（FFI 绑定）
        ▼
  Zig 运行时 (runtime/zig/)
        │
        │  MurmurHash3-32 syscall 派发
        ▼
    Solana BPF
```

具体来说，有 **三种不同的扩展场景**：

---

### 场景 1：加一个新的 Syscall / Sysvar / 哈希算法

**→ 只需要写 Zig**

例如如果要加 `sol_get_epoch_schedule_sysvar`，只需：

1. 在 `runtime/zig/syscalls.zig` 加一个 MurmurHash3-32 地址 + Zig 包装函数
2. 在 `stdlib/core.ml` 加一行 `external` 声明让 OCaml 可以调用

```ocaml
(* stdlib/core.ml — OCaml 侧只需一行声明 *)
external epoch_schedule_sysvar : unit -> epoch_schedule = "sol_get_epoch_schedule_sysvar"
```

```zig
// runtime/zig/syscalls.zig — Zig 侧做实际 syscall 派发
pub const sol_get_epoch_schedule_sysvar_address: usize = 0x????????;
pub inline fn sol_get_epoch_schedule_sysvar() EpochSchedule {
    if (comptime is_bpf) {
        // BPF 环境：调用 Solana syscall
        const syscall: SolGetEpochScheduleSysvarFn = @ptrFromInt(sol_get_epoch_schedule_sysvar_address);
        var schedule: EpochSchedule = undefined;
        _ = syscall(&schedule);
        return schedule;
    }
    return .{}; // hosted fallback
}
```

---

### 场景 2：加一个新的 SPL Token 指令（如 Token-2022）

**→ 主要写 Zig + 少量 OCaml 声明**

比如要加 `SetAuthority` 指令：

```zig
// runtime/zig/spl_token.zig — Zig 侧做指令编码
pub const set_authority_discriminator: u8 = 6;
pub const set_authority_instruction_data_len: usize = 1 + 1 + 32; // disc + type + new_authority

pub fn encodeSetAuthority(authority_type: u8, new_authority: *const Pubkey) [set_authority_instruction_data_len]u8 {
    var out: [set_authority_instruction_data_len]u8 = undefined;
    out[0] = set_authority_discriminator;
    out[1] = authority_type;
    @memcpy(out[2..34], new_authority[0..]);
    return out;
}

pub fn setAuthorityAccountMetas(account: *const Pubkey, authority: *const Pubkey) [2]cpi.SolAccountMeta {
    return .{
        .{ .pubkey = account, .is_writable = 1, .is_signer = 0 },
        .{ .pubkey = authority, .is_writable = 0, .is_signer = 1 },
    };
}
```

---

### 场景 3：写一个有真实业务逻辑的链上程序

**→ OCaml 做调度，Zig 做"脏活"**

这是当前最复杂的模式。以 `dao_voting` 为例：

```ocaml
(* examples/dao_voting.ml — OCaml 侧：路由 + 声明 *)
external dao_voting_process : account -> account -> account -> bytes -> int
  = "dao_voting_process"

let entrypoint proposal vote_record voter instruction_data =
  (* OCaml 只做指令路由 *)
  let _ = log_message "DAO voting program: starting" in
  dao_voting_process proposal vote_record voter instruction_data
```

```zig
// runtime/zig/programs/dao_voting.zig — Zig 侧：账户校验、PDA 验证、数据读写
fn createProposal(program_id: *const Pubkey, views: []AccountView, instruction_data: []const u8) u64 {
    // 1. 校验账户权限
    // 2. 验证 PDA 地址匹配
    // 3. 写入提案数据（title、deadline、初始计数器）
    @memcpy(proposal.data[0..32], instruction_data[17..49]);  // title
    writeU64Le(proposal.data[32..40], 0);                      // yes = 0
    writeU64Le(proposal.data[40..48], 0);                      // no  = 0
    writeU64Le(proposal.data[48..56], deadline);               // deadline
    return 0;
}
```

**为什么复杂程序需要 Zig？** 因为 ZxCaml 的 OCaml 子集目前不支持：
- 直接字节操作（`@memcpy`、按位读写）
- unsafe 指针操作（零拷贝账户视图）
- PDA 种子构造和验证
- 原始内存布局读写（LE 编码的 u64）

---

### 总结：谁写什么

| 要做的事 | 写什么语言 | 原因 |
|---|---|---|
| 新 syscall 绑定 | **Zig** + OCaml `external` 声明 | 只有 Zig 能做 BPF syscall 派发 |
| 新 Sysvar 读取 | **Zig** 解析器 + OCaml `external` | 账户数据布局解析需要直接字节操作 |
| 新 SPL 指令编码 | **Zig** 编码器 + 可选 OCaml 封装 | 指令数据是紧凑二进制格式 |
| 新的程序入口点胶水 | **Zig** (`bpf_entry.zig`) | BPF 入口点必须是 Zig 导出的 C ABI |
| 程序逻辑路由/分发 | **OCaml** | discriminator 匹配、条件分支 |
| 简单的 CPI 调用 | **纯 OCaml** | `invoke_signed` + `instruction` record 已在 stdlib |
| 复杂账户状态操作 | **Zig** `runtime/zig/programs/xxx.zig` | 需要直接操作账户 data 字节 |
| 纯计算逻辑 | **纯 OCaml** | 编译器能完整处理 |

**一句话概括**：OCaml 负责表达"你想做什么"（业务逻辑路由），Zig 负责"怎么跟 Solana 机器打交道"（syscall、字节布局、PDA、内存）。要扩展 Solana SDK 支持范围，**Zig 是主要战场**。

//! CONTRACT: Core IR data model for the ZxCaml compiler pipeline.
//!
//! This file is the stable Core IR contract described by `docs/03-core-ir.md`;
//! changes to its shape must update all consumers in the same commit.
//!
//! RESPONSIBILITIES:
//! - Represent the ANF, typed, Layout-tagged Core IR data model.
//! - Keep allocation-bearing nodes explicit about their `Layout`.
//! - Serve consumers: `anf`, `lower`, `interp`, `zig_codegen`, and `pretty`.
//! - Preserve pattern-match order: arms are tested top-to-bottom and the first
//!   matching arm wins in every backend.
//!
//! Ctor layout policy (F10/F13):
//! ```text
//! Some(x) -> Ctor { name = "Some", args = [x],
//!                   ty = option<int>,
//!                   layout = { region = Arena, repr = Boxed } }
//!   The backend heap-allocates the discriminant plus payload in the arena,
//!   because payload-bearing ADT values are boxed in P1.
//!
//! None    -> Ctor { name = "None", args = [],
//!                   ty = option<int>,
//!                   layout = { region = Static, repr = TaggedImmediate } }
//!   The value is zero-sized at runtime: only the constructor tag is needed.
//!
//! Ok(x) and Error(e) follow the same result<T,E> rule: payload variants are
//! Arena/Boxed, while future nullary variants would be Static/TaggedImmediate.
//!
//! (::)(head, tail) -> Ctor { name = "::", args = [head, tail],
//!                            ty = list<int>,
//!                            layout = { region = Arena, repr = Boxed } }
//!   Cons cells are heap-allocated in the arena; the runtime payload stores
//!   the head plus a tail pointer.
//!
//! [] -> Ctor { name = "[]", args = [],
//!              ty = list<int>,
//!              layout = { region = Static, repr = TaggedImmediate } }
//!   Nil is zero-sized at runtime: only the empty-list discriminant is needed.
//! ```

const layout = @import("layout.zig");
const types = @import("types.zig");

/// Optional source location threaded from frontend wire 1.2.
pub const Loc = struct {
    file: []const u8,
    line: u32,
    col: u32,
    end_line: u32,
    end_col: u32,

    pub const unknown: Loc = .{
        .file = "_unknown_",
        .line = 0,
        .col = 0,
        .end_line = 0,
        .end_col = 0,
    };

    pub fn isUnknown(self: Loc) bool {
        return self.line == 0 and self.end_line == 0;
    }
};

/// A Core IR module containing top-level declarations.
pub const Module = struct {
    decls: []const Decl,
    type_decls: []const types.VariantType = &.{},
    tuple_type_decls: []const types.TupleType = &.{},
    record_type_decls: []const types.RecordType = &.{},
    externals: []const ExternalDecl = &.{},
};

/// Top-level Core IR declarations.
pub const Decl = union(enum) {
    Let: Let,
    LetGroup: LetGroup,
};

/// Top-level external function declaration with its direct Zig symbol.
pub const ExternalDecl = struct {
    name: []const u8,
    ty: Ty,
    symbol: []const u8,
};

/// Top-level let declaration.
pub const Let = struct {
    name: []const u8,
    value: *const Expr,
    ty: Ty,
    layout: layout.Layout,
    is_rec: bool = false,
};

/// One function binding in a mutually recursive group.
pub const LetGroupBinding = struct {
    name: []const u8,
    value: *const Expr,
    ty: Ty,
    layout: layout.Layout,
};

/// Top-level mutually recursive group.
pub const LetGroup = struct {
    bindings: []const LetGroupBinding,
};

/// Core IR lambda in ANF form.
pub const Lambda = struct {
    params: []const Param,
    body: *const Expr,
    ty: Ty,
    layout: layout.Layout,
    loc: ?Loc = null,
};

/// Lambda parameter with a resolved type.
pub const Param = struct {
    name: []const u8,
    ty: Ty,
};

/// Core IR expression.
pub const Expr = union(enum) {
    Lambda: Lambda,
    Constant: Constant,
    App: App,
    Let: LetExpr,
    LetGroup: LetGroupExpr,
    Assert: AssertExpr,
    If: IfExpr,
    Prim: Prim,
    Var: Var,
    Ctor: Ctor,
    Match: Match,
    Tuple: Tuple,
    TupleProj: TupleProj,
    Record: Record,
    RecordField: RecordField,
    RecordUpdate: RecordUpdate,
    AccountFieldSet: AccountFieldSet,
};

/// Returns the optional source location carried by any Core IR expression.
pub fn exprLoc(expr: Expr) ?Loc {
    return switch (expr) {
        .Lambda => |value| value.loc,
        .Constant => |value| value.loc,
        .App => |value| value.loc,
        .Let => |value| value.loc,
        .LetGroup => |value| value.loc,
        .Assert => |value| value.loc,
        .If => |value| value.loc,
        .Prim => |value| value.loc,
        .Var => |value| value.loc,
        .Ctor => |value| value.loc,
        .Match => |value| value.loc,
        .Tuple => |value| value.loc,
        .TupleProj => |value| value.loc,
        .Record => |value| value.loc,
        .RecordField => |value| value.loc,
        .RecordUpdate => |value| value.loc,
        .AccountFieldSet => |value| value.loc,
    };
}

/// Overwrites the optional source location on any Core IR expression.
pub fn setExprLoc(expr: *Expr, loc: ?Loc) void {
    switch (expr.*) {
        .Lambda => |*value| value.loc = loc,
        .Constant => |*value| value.loc = loc,
        .App => |*value| value.loc = loc,
        .Let => |*value| value.loc = loc,
        .LetGroup => |*value| value.loc = loc,
        .Assert => |*value| value.loc = loc,
        .If => |*value| value.loc = loc,
        .Prim => |*value| value.loc = loc,
        .Var => |*value| value.loc = loc,
        .Ctor => |*value| value.loc = loc,
        .Match => |*value| value.loc = loc,
        .Tuple => |*value| value.loc = loc,
        .TupleProj => |*value| value.loc = loc,
        .Record => |*value| value.loc = loc,
        .RecordField => |*value| value.loc = loc,
        .RecordUpdate => |*value| value.loc = loc,
        .AccountFieldSet => |*value| value.loc = loc,
    }
}

/// Function application expression.
pub const App = struct {
    callee: *const Expr,
    args: []const *const Expr,
    ty: Ty,
    layout: layout.Layout,
    is_tail_call: bool = false,
    loc: ?Loc = null,
};

/// Lexically-scoped let expression in ANF form.
pub const LetExpr = struct {
    name: []const u8,
    value: *const Expr,
    body: *const Expr,
    ty: Ty,
    layout: layout.Layout,
    is_rec: bool = false,
    loc: ?Loc = null,
};

/// Lexically-scoped mutually recursive group in ANF form.
pub const LetGroupExpr = struct {
    bindings: []const LetGroupBinding,
    body: *const Expr,
    ty: Ty,
    layout: layout.Layout,
    loc: ?Loc = null,
};

/// Runtime assertion that traps when its boolean condition is false.
pub const AssertExpr = struct {
    condition: *const Expr,
    ty: Ty,
    layout: layout.Layout,
    loc: ?Loc = null,
};

/// Conditional expression.
pub const IfExpr = struct {
    cond: *const Expr,
    then_branch: *const Expr,
    else_branch: *const Expr,
    ty: Ty,
    layout: layout.Layout,
    loc: ?Loc = null,
};

/// Primitive integer/comparison operation.
pub const Prim = struct {
    op: PrimOp,
    args: []const *const Expr,
    ty: Ty,
    layout: layout.Layout,
    loc: ?Loc = null,
};

/// Primitive operations supported by the current Core IR.
pub const PrimOp = enum {
    Add,
    Sub,
    Mul,
    Div,
    Mod,
    Eq,
    Ne,
    Lt,
    Le,
    Gt,
    Ge,
    StringLength,
    StringGet,
    StringSub,
    StringConcat,
    CharCode,
    CharChr,
};

/// Integer constant expression with type and layout annotations.
pub const Constant = struct {
    value: ConstantValue,
    ty: Ty,
    layout: layout.Layout,
    loc: ?Loc = null,
};

/// Literal payload carried by a constant expression.
pub const ConstantValue = union(enum) {
    Int: i64,
    String: []const u8,
};

/// Variable reference with type and layout inherited from its binding.
pub const Var = struct {
    name: []const u8,
    ty: Ty,
    layout: layout.Layout,
    loc: ?Loc = null,
};

/// Constructor expression for whitelisted option/result/list ADTs.
pub const Ctor = struct {
    name: []const u8,
    args: []const *const Expr,
    ty: Ty,
    layout: layout.Layout,
    tag: u32 = 0,
    type_name: ?[]const u8 = null,
    loc: ?Loc = null,
};

/// Tuple construction expression.
pub const Tuple = struct {
    items: []const *const Expr,
    ty: Ty,
    layout: layout.Layout,
    loc: ?Loc = null,
};

/// Tuple projection expression.
pub const TupleProj = struct {
    tuple_expr: *const Expr,
    index: usize,
    ty: Ty,
    layout: layout.Layout,
    loc: ?Loc = null,
};

/// Record construction expression.
pub const Record = struct {
    fields: []const RecordExprField,
    ty: Ty,
    layout: layout.Layout,
    loc: ?Loc = null,
};

/// One field assignment in a record construction/update expression.
pub const RecordExprField = struct {
    name: []const u8,
    value: *const Expr,
};

/// Record field access expression.
pub const RecordField = struct {
    record_expr: *const Expr,
    field_name: []const u8,
    ty: Ty,
    layout: layout.Layout,
    loc: ?Loc = null,
};

/// Functional record update expression.
pub const RecordUpdate = struct {
    base_expr: *const Expr,
    fields: []const RecordExprField,
    ty: Ty,
    layout: layout.Layout,
    loc: ?Loc = null,
};

/// AccountFieldSet is the sole mutating Core/ANF expression.
/// It preserves ANF because account-field writes are effects threaded through
/// let/program order, not nested as operands inside other expressions.
/// The ANF lowering pass in src/core/anf/module.zig emits it from writable
/// Solana account-field updates.
pub const AccountFieldSet = struct {
    account_expr: *const Expr,
    field_name: []const u8,
    value: *const Expr,
    ty: Ty,
    layout: layout.Layout,
    loc: ?Loc = null,
};

/// Pattern match expression; arms are evaluated top-to-bottom.
pub const Match = struct {
    scrutinee: *const Expr,
    arms: []const Arm,
    ty: Ty,
    layout: layout.Layout,
    loc: ?Loc = null,
};

/// One pattern-match arm.
pub const Arm = struct {
    pattern: Pattern,
    guard: ?*const Expr = null,
    body: *const Expr,
};

/// Recursive pattern subset used by match arms.
pub const Pattern = union(enum) {
    Wildcard,
    Var: PatternVar,
    Constant: PatternConstant,
    Ctor: PatternCtor,
    Tuple: []const Pattern,
    Record: []const RecordPatternField,
    Alias: PatternAlias,
};

/// Literal constant pattern used by match arms.
pub const PatternConstant = union(enum) {
    Int: i64,
    String: []const u8,
    Char: i64,
};

/// Alias pattern that binds the full matched value in addition to nested bindings.
pub const PatternAlias = struct {
    pattern: *const Pattern,
    name: []const u8,
    ty: Ty,
    layout: layout.Layout,
};

/// Variable pattern that binds the matched value into the arm body.
pub const PatternVar = struct {
    name: []const u8,
    ty: Ty,
    layout: layout.Layout,
};

/// Constructor pattern such as `Some x`, `None`, `Ok x`, `Error e`, `[]`, `x :: xs`, or nested constructor payloads.
pub const PatternCtor = struct {
    name: []const u8,
    args: []const Pattern,
    tag: u32 = 0,
    type_name: ?[]const u8 = null,
};

/// One field pattern inside a record pattern.
pub const RecordPatternField = struct {
    name: []const u8,
    pattern: Pattern,
};

/// M1 type language needed to describe current examples.
pub const Ty = union(enum) {
    Int,
    Bool,
    Unit,
    String,
    Var: []const u8,
    Adt: Adt,
    Tuple: []const Ty,
    Record: RecordTy,
    Arrow: Arrow,
};

/// Algebraic data type reference with concrete parameter types.
pub const Adt = struct {
    name: []const u8,
    params: []const Ty,
};

/// Multi-argument arrow type.
pub const Arrow = struct {
    params: []const Ty,
    ret: *const Ty,
};

/// Nominal record type reference with concrete parameter types.
pub const RecordTy = struct {
    name: []const u8,
    params: []const Ty,
};

