(* Test bitwise operations: land, lor, lxor, lsl, lsr, lnot *)

let test_bit_and () =
  let x = 0xFF land 0x0F in
  x

let test_bit_or () =
  let x = 0xF0 lor 0x0F in
  x

let test_bit_xor () =
  let x = 0xFF lxor 0xFF in
  x

let test_shift_left () =
  let x = 1 lsl 8 in
  x

let test_shift_right () =
  let x = 256 lsr 4 in
  x

let test_bit_not () =
  let x = lnot 0 in
  x

(* Encode a u16 little-endian into two bytes *)
let encode_u16_le value =
  let lo = (value land 0xFF) in
  let hi = ((value lsr 8) land 0xFF) in
  (lo, hi)

let entrypoint _ =
  let a = test_bit_and () in   (* 0x0F = 15 *)
  let b = test_bit_or () in    (* 0xFF = 255 *)
  let c = test_bit_xor () in   (* 0 *)
  let d = test_shift_left () in (* 256 *)
  let e = test_shift_right () in (* 16 *)
  let f = test_bit_not () in   (* -1 *)
  let (lo, hi) = encode_u16_le 0x1234 in
  (* lo = 0x34 = 52, hi = 0x12 = 18 *)
  a + b + c + d + e + f + lo + hi

