pub fn primOpToken(op: lir.LPrimOp) []const u8 {
    return switch (op) {
        .Add => "+%",
        .Sub => "-%",
        .Mul => "*%",
        .Eq => "==",
        .Ne => "!=",
        .Lt => "<",
        .Le => "<=",
        .Gt => ">",
        .Ge => ">=",
        .Div, .Mod, .StringLength, .StringGet, .StringSub, .StringConcat, .CharCode, .CharChr, .BitAnd, .BitOr, .BitXor, .ShiftLeft, .ShiftRight, .BitNot => unreachable,
    };
}

