(* Demonstrates a P3 SPL Token transfer built as a CPI.
   The example uses the Tokenkeg program id, source/destination/authority
   account metas, the Transfer instruction bytes, and invokes the token program. *)

let entrypoint _accounts _input =
  (* SPL Token transfer flow: amount is encoded below in the instruction data. *)
  let amount = 1 in
  (* Keep the amount binding visible to the example and to the compiler pipeline. *)
  let _ = amount in
  (* CPI construction: invoke_signed forwards the token transfer instruction
     with no PDA signer seeds for this harness path. *)
  invoke_signed
    {
      (* Legacy SPL Token program id used by the acceptance harness. *)
      program_id = Pubkey.token_program;
      (* SPL Token Transfer accounts:
         source token account (writable), destination token account (writable),
         and authority (signer).  The harness supplies the concrete pubkeys. *)
      accounts =
        Array.of_list
          [
            { pubkey = Bytes.of_string ""; is_writable = true; is_signer = false };
            { pubkey = Bytes.of_string ""; is_writable = true; is_signer = false };
            { pubkey = Bytes.of_string ""; is_writable = false; is_signer = true };
          ];
      (* Transfer instruction payload: discriminator 3 followed by amount=1
         as little-endian u64 bytes. *)
      data = Bytes.of_string "\003\001\000\000\000\000\000\000\000";
    }
    (* No PDA signer seeds are required for the basic authority-signed transfer. *)
    (Array.of_list [])

(* Demonstrates P3 cross-program invocation (CPI).
   The instruction below is shaped like a System Program transfer: it names the
   callee program, marks source/destination account metas, supplies transfer
   data, and invokes with signer seeds. *)

external log_message : string -> unit = "sol_log_"

let entrypoint accounts input =
  let _ = accounts in
  let _ = input in
  let _ = log_message "simple CPI via external binding" in
  (* CPI construction: invoke_signed receives the instruction record and the
     signer seed arrays needed when a program signs on behalf of a PDA. *)
  invoke_signed
    {
      (* The native System Program has the all-zero 32-byte program id. *)
      program_id = Pubkey.zero;
      (* Account metas describe the privileges forwarded to the callee:
         a writable signer source and a writable non-signer destination. *)
      accounts =
        Array.of_list
          [
            {
              pubkey = Pubkey.zero;
              is_writable = true;
              is_signer = true;
            };
            {
              pubkey = Pubkey.zero;
              is_writable = true;
              is_signer = false;
            };
          ];
      (* System transfer instruction data: discriminator 2 plus amount 1
         encoded as little-endian bytes for the runtime CPI helper. *)
      data =
        Bytes.of_string
          "\002\000\000\000\001\000\000\000\000\000\000\000";
    }
    (* Signer seeds are nested arrays of byte slices; this smoke test includes
       one seed group containing the literal "zxcaml". *)
    (Array.of_list [ Array.of_list [ Bytes.of_string "zxcaml" ] ])

