/// One-step BPF build using solana-zig (built-in Solana LLVM fork).
/// Returns true on success, false if solana-zig is not available.
/// Activated only when SOLANA_ZIG env var is set to a truthy value.
pub fn buildBpfDirect(allocator: Allocator, io: Io, options: BpfBuildOptions) !bool {
    // Only activate when explicitly opted in via SOLANA_ZIG=1 or SOLANA_ZIG=path
    const posix_block = switch (options.environ.block) {
        .PosixBlock => |pb| pb,
        else => return false,
    };
    const solana_zig: ?[]const u8 = blk: {
        for (posix_block.slice) |entry_opt| {
            const entry = entry_opt orelse continue;
            const str = std.mem.sliceTo(entry, 0);
            if (!std.mem.startsWith(u8, str, "SOLANA_ZIG=")) continue;
            const val = str["SOLANA_ZIG=".len..];
            if (val.len == 0 or std.mem.eql(u8, val, "0")) break :blk null;
            if (std.mem.eql(u8, val, "1")) break :blk "solana-zig";
            break :blk val; // custom path
        }
        break :blk null;
    } orelse return false;

    return try buildBpfDirectWith(allocator, io, solana_zig, options);
}

