            if (!std.mem.startsWith(u8, str, "SOLANA_ZIG=")) continue;
            const val = str["SOLANA_ZIG=".len..];
            if (val.len == 0 or std.mem.eql(u8, val, "0")) break :blk null;
            if (std.mem.eql(u8, val, "1")) break :blk "solana-zig";
            break :blk val; // custom path
        }
        break :blk null;
    } orelse return false;

    return try buildBpfDirectWith(allocator, io, solana_zig, options);
}

